"""Fake external KMS/HSM provider for testing the module:factory path.

Its backend store persists to $FAKEKMS_DIR/backend.json so separate CLI
processes share the same handle namespace. Failure knobs:
- FAKEKMS_FAIL_OP: comma list of operations that raise RuntimeError;
- FAKEKMS_FAIL_FACTORY=1 makes the factory raise;
- FAKEKMS_BAD_CONTRACT=1 makes the factory return an object missing methods.
"""

import json
import os
import threading

_BACKEND = None
_LOCK = threading.Lock()

CAPS = {
    "algorithms": ["AES256", "RSA2048"],
    "operations": [
        "generate",
        "rotate",
        "import_material",
        "export_material",
        "delete",
    ],
}


def _dir():
    d = os.environ.get("FAKEKMS_DIR", "/tmp/fakekms-default")
    os.makedirs(d, exist_ok=True)
    return d


def _path():
    return os.path.join(_dir(), "backend.json")


def _load():
    global _BACKEND
    if _BACKEND is None:
        try:
            with open(_path(), "r", encoding="utf-8") as fh:
                _BACKEND = json.load(fh)
        except (OSError, ValueError):
            _BACKEND = {}
    return _BACKEND


def _save():
    tmp = _path() + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(_BACKEND, fh)
    os.replace(tmp, _path())


class FakeKMS:
    provider_id = "fakekms-1"
    capabilities = CAPS

    def _maybe_fail(self, op):
        fails = set(os.environ.get("FAKEKMS_FAIL_OP", "").split(","))
        if op in fails:
            raise RuntimeError("SECRET-backend-text/%s/boom" % op)

    def generate(self, algorithm):
        self._maybe_fail("generate")
        return self.rotate(algorithm)

    def rotate(self, algorithm):
        self._maybe_fail("rotate")
        # Delegate to the real local material logic by importing lazily so the
        # fake stays self-contained; the *backend* is still this fake object.
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric import rsa
        import base64 as _b64

        handle = "fh-" + os.urandom(8).hex()
        if algorithm == "AES256":
            raw = os.urandom(32)
            material = _b64.b64encode(raw).decode()
            public = None
        else:
            pk = rsa.generate_private_key(65537, 2048)
            material = pk.private_bytes(
                serialization.Encoding.PEM,
                serialization.PrivateFormat.PKCS8,
                serialization.NoEncryption(),
            ).decode()
            public = pk.public_key().public_bytes(
                serialization.Encoding.PEM,
                serialization.PublicFormat.SubjectPublicKeyInfo,
            ).decode()
        with _LOCK:
            _load()[handle] = {
                "algorithm": algorithm,
                "public_key": public,
                "material": material,
            }
            _save()
        return {
            "handle": handle,
            "public_key": public,
            "encrypted_material": "ENC[" + material + "]",
        }

    def import_material(self, algorithm, public_key, material):
        self._maybe_fail("import_material")
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric import rsa

        if algorithm == "AES256":
            import base64 as _b64

            raw = _b64.b64decode(material, validate=True)
            if len(raw) != 32:
                raise ValueError("bad aes material length")
        else:
            pk = serialization.load_pem_private_key(
                material.encode(), password=None
            )
            if not isinstance(pk, rsa.RSAPrivateKey) or pk.key_size != 2048:
                raise ValueError("bad rsa key")
        handle = "fh-" + os.urandom(8).hex()
        with _LOCK:
            _load()[handle] = {
                "algorithm": algorithm,
                "public_key": public_key,
                "material": material,
            }
            _save()
        return {
            "handle": handle,
            "public_key": public_key,
            "encrypted_material": "ENC[" + material + "]",
        }

    def export_material(self, handle):
        self._maybe_fail("export_material")
        with _LOCK:
            obj = _load().get(handle)
        if obj is None:
            raise RuntimeError("SECRET unknown handle " + handle)
        return {
            "public_key": obj["public_key"],
            "encrypted_material": obj["material"],
        }

    def delete(self, handle):
        self._maybe_fail("delete")
        with _LOCK:
            _load().pop(handle, None)
            _save()


def factory():
    if os.environ.get("FAKEKMS_FAIL_FACTORY") == "1":
        raise RuntimeError("SECRET factory exploded")
    if os.environ.get("FAKEKMS_BAD_CONTRACT") == "1":
        class Bad:
            provider_id = "bad"
        return Bad()
    return FakeKMS()

